#include "ksPanelDetectTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
int main(){using T=ks::PanelDetectTask;using S=T::Stage;using W=T::Write;unsigned cases=0;for(unsigned sense=0;sense<256;++sense)for(unsigned budget:{0u,1u,3u,8u,11u,12u,17u,100u,65535u}){T t;unsigned used=0,reads=0;std::vector<std::pair<W,unsigned>>writes;while(t.stage()!=S::Complete){auto cost=t.nextClocks();if(t.advanceBefore(cost-1,[]()->unsigned{throw std::runtime_error("early read");},[](W,uint8_t){throw std::runtime_error("early write");}))throw std::runtime_error("early budget");used+=t.advanceBefore(budget<cost?cost:budget,[&]{++reads;return sense;},[&](W w,uint8_t v){writes.emplace_back(w,v);});}std::vector<std::pair<W,unsigned>>expected{{W::Presence,0},{W::Gate,1},{W::Latch,254}};if(sense&128){expected.emplace_back(W::Latch,1);expected.emplace_back(W::Gate,255);}else expected.emplace_back(W::Presence,255);if(writes!=expected||used!=((sense&128)?16116:16114)||reads!=1||t.sense()!=sense||t.present()!=!(sense&128)||t.inner()||t.outer())throw std::runtime_error("panel detect order/delay/clocks");++cases;}std::cout<<"PASS: "<<cases<<" pure panel-detect properties\n";}
